callGraph.callee:
items
                .iter()
                .filter_map(|item| {
                    let vals = crate::client::skill_sexp::sexp_to_str_list(item)?;
                    if vals.len() != fields.len() {
                        return None;
                    }
                    Some(
                        fields
                            .iter()
                            .zip(vals.iter())
                            .map(|(k, v)| (k.to_string(), v.clone().unwrap_or_default()))
                            .collect(),
                    )
                }).collect

s.chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() || c == '-' || c == '_' || c == '.' {
                c
            } else {
                '_'
            }
        }).collect

obj
        .iter()
        .map(|(k, v)| {
            let binding = v.to_string();
            let val = v.as_str().unwrap_or(&binding);
            format!("(\"{k}\" \"{val}\")")
        }).collect

parse_skill_json(&r.output)
                .and_then(|v| {
                    v.as_array()
                        .map(|arr| {
                            arr.iter()
                                .filter_map(|e| e.as_str().map(String::from))
                                .collect()
                        })
                        .ok_or_else(|| VirtuosoError::Execution("expected array".into()))
                }).unwrap_or_default

params
                    .iter()
                    .map(|p| {
                        let signal = format!("{inst}:{p}");
                        format!(
                            "value(getData({} ?result \"dcOpInfo\"))",
                            string_literal(&signal)
                        )
                    }).collect
